def ants_ai_outputs(params: AntsAi, execution: Execution) -> AntsAiOutputs:
    """Build the AntsAiOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    output_transform_v: OutputPathType = execution.output_file(params["output"])
    return AntsAiOutputs(
        root=root_v,
        output_transform=output_transform_v,
    )

def ants_ai_execute(params: AntsAi, runner: Runner | None = None) -> AntsAiOutputs:
    """
    antsAI

    Program to calculate the optimal linear transform parameters for aligning two images.

    Author: ANTs Developers

    URL: https://github.com/ANTsX/ANTs

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    ants_ai_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(ANTS_AI_METADATA)
    execution.params(params)
    args = ants_ai_cargs(params, execution)
    out = ants_ai_outputs(params, execution)
    execution.run(args)
    return out

def ants_ai(
    metric: AntsAiMetric,
    transform: AntsAiTransform,
    output: str,
    dimensionality: AntsAiDimensionality | None = None,
    align_principal_axes: bool | None = None,
    align_blobs: AntsAiAlignBlobs | None = None,
    search_factor: AntsAiSearchFactor | None = None,
    translation_search_grid: AntsAiTranslationSearchGrid | None = None,
    convergence: AntsAiConvergence | None = None,
    masks: AntsAiMasks | None = None,
    random_seed: int | None = None,
    verbose: bool | None = None,
    runner: Runner | None = None,
) -> AntsAiOutputs:
    """
    antsAI

    Program to calculate the optimal linear transform parameters for aligning two images.

    Author: ANTs Developers

    URL: https://github.com/ANTsX/ANTs

    Args:
        metric: Image similarity metric. Available metrics: Mattes (Mattes mutual\
            information, recommended), GC (global correlation), MI (joint histogram\
            mutual information). Each metric takes a fixed and moving image, with\
            optional sampling parameters.
        transform: Transform type for alignment. The rigid, affine, and similarity\
            transforms take a gradient step parameter that characterizes the\
            gradient descent optimization and is scaled appropriately for each\
            transform using the shift scales estimator. AlignGeometricCenters and\
            AlignCentersOfMass find the simple translation transform aligning the\
            specified image feature. Note that the images are read from the metric\
            option although the metric value itself is not used for the latter two.
        output: Specify the output transform filename (output format is an ITK .mat\
            file).
        dimensionality: This option forces the image to be treated as a\
            specified-dimensional image. If not specified, we try to infer the\
            dimensionality from the input image.
        align_principal_axes: Align images by their principal axes. Alternatively,\
            one can align using blobs (see --align-blobs option).
        align_blobs: Align images using a set of extracted blobs. Specify the\
            number of blobs to extract, and optionally the number of blobs to match\
            (defaults to numberOfBlobsToExtract). Alternatively, one can align\
            using principal axes (see --align-principal-axes option).
        search_factor: Incremental search factor (in degrees) which will sample the\
            arc fraction around the principal axis or default axis. Default search\
            factor is 20 degrees with an arc fraction of 1.0.
        translation_search_grid: Translation search grid in mm, which will\
            translate the moving image in each dimension in increments of the step\
            size.
        convergence: Convergence parameters for the optimization. Specify the\
            number of iterations, and optionally a convergence threshold (default\
            1e-6) and convergence window size (default 10).
        masks: Image masks to limit the voxels considered by the metric. Specify a\
            fixed image mask, and optionally a moving image mask.
        random_seed: Use a fixed seed for random number generation. The default\
            fixed seed is overwritten by this value. The fixed seed can be any\
            nonzero int value. If the specified seed is zero, the system time will\
            be used.
        verbose: Verbose output. Default is 0 (off).
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    params = ants_ai_params(
        metric=metric,
        transform=transform,
        output=output,
        dimensionality=dimensionality,
        align_principal_axes=align_principal_axes,
        align_blobs=align_blobs,
        search_factor=search_factor,
        translation_search_grid=translation_search_grid,
        convergence=convergence,
        masks=masks,
        random_seed=random_seed,
        verbose=verbose,
    )
    return ants_ai_execute(params, runner)

